const $=(q,r=document)=>r.querySelector(q);const $$=(q,r=document)=>[...r.querySelectorAll(q)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n.toFixed(4)).toLocaleString('sv-SE',{maximumFractionDigits:4});
const math=(s,cls='')=>`<span class="tex ${cls}" data-tex="${esc(s)}">${esc(s)}</span>`;
function tex(root=document){$$('[data-tex]',root).forEach(el=>{if(window.katex)window.katex.render(el.dataset.tex,el,{throwOnError:false,output:'htmlAndMathml',trust:false});});}
const topics=[
 {title:'Algebraiska uttryck',short:'Uttryck',lab:'Uttrycksbyggaren',desc:'Ge bokstäver ett värde. Se hur hela uttrycket förändras.',intro:'Dra in byggstenar, skapa egna uttryck och ändra x. Spara ett bygge och jämför vad som händer när variabeln byter värde.',icon:'3x+2',film:'01-uttryck',insight:'En variabel är en plats för ett tal. 3x betyder 3 · x. Samma x har samma värde på alla ställen i ett uttryck.',question:'Förutsäg först: om x ökar med 1, hur mycket ökar 3x + 2?'},
 {title:'Mönster',short:'Mönster',lab:'Mönsterbyggaren',desc:'Bygg växande figurer och hitta regeln bakom dem.',intro:'En liten förändring kan bli en stor idé. Bygg ett mönster, följ det som växer och upptäck en regel för alla figurer.',icon:'3n+2',film:'02-monster',insight:'Den fasta delen finns redan från början. Den växande delen upprepas en gång för varje figurnummer. Figur n har därför 3n + 2 brickor i startmönstret.',question:'Kan du räkna ut figur 20 utan att bygga alla figurer fram till den?'},
 {title:'Förenkling av uttryck',short:'Förenkla',lab:'Termverkstaden',desc:'Samla liknande termer. Låt tecknet följa med.',intro:'Bygg egna uttryck med positiva och negativa brickor. Dra termerna till rätt grupper och undersök hur nollpar försvinner.',icon:'4x+2x=6x',film:'03-forenkla',insight:'Bara liknande termer kan läggas ihop: x med x och tal med tal. Minustecknet tillhör termen. x + 3 kan inte förenklas till 4x.',question:'Hur kan två uttryck se olika ut och ändå alltid ha samma värde?'},
 {title:'Ekvationer',short:'Ekvationer',lab:'Balanslabbet',desc:'Hitta det okända genom att bevara likheten.',intro:'En ekvation säger att två uttryck har samma värde. Prova x och använd sedan samma operation i båda leden för att hitta lösningen.',icon:'3x+4=19',film:'04-ekvationer',insight:'Likhetstecknet betyder att vänsterled och högerled är lika stora. Samma operation i båda leden bevarar lösningen. Kontrollera alltid i ursprungsekvationen.',question:'Varför behöver vi göra samma sak på båda sidor?'},
 {title:'Problemlösning med ekvationer',short:'Problemlösning',lab:'Nöjesparkslabbet',desc:'Förvandla en berättelse till matematik.',intro:'Du har en budget till nöjesparken. Utforska kostnaden, bygg en ekvation och tolka vad lösningen betyder i verkligheten.',icon:'35+15x=125',film:'05-problem',insight:'Bestäm vad x betyder innan du skriver ekvationen. Här är x antalet åkturer, alltså ett heltal. Lösningen behöver en enhet och ska passa berättelsen.',question:'Hur många åkturer räcker pengarna till efter att entrén är betald?'},
 {title:'Obekanta i båda leden',short:'Båda leden',lab:'Två sidor, ett x',desc:'Följ samma x på båda sidor av likhetstecknet.',intro:'Nu finns x i båda leden. Samla x-termerna med samma operation på båda sidor. Undersök även ekvationer med ingen eller många lösningar.',icon:'4x+2=2x+12',film:'06-bada-led',insight:'En ekvation kan ha exakt en lösning, ingen lösning eller vara sann för alla värden på x. Om x-termerna försvinner behöver du undersöka vad som återstår.',question:'Vad händer om lika många x försvinner från båda leden?'}
];
const storage={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let progress=storage.get('algebra-progress-v1',{}),reduced=storage.get('algebra-motion',matchMedia('(prefers-reduced-motion: reduce)').matches),active=-1,tab='explore',level='start',task=null,seed=Date.now()%1000000,cleanup=()=>{};
function setMotion(v){reduced=v;document.body.classList.toggle('reduce-motion',v);$('#motion').setAttribute('aria-pressed',v);$('#motion-mobile').setAttribute('aria-pressed',v);storage.set('algebra-motion',v);document.dispatchEvent(new CustomEvent('algebra-motion-change',{detail:v}));}setMotion(reduced);
$('#motion').onclick=()=>setMotion(!reduced);
$('#motion-mobile').onclick=()=>{setMotion(!reduced);$('#motion-mobile').setAttribute('aria-pressed',reduced)};
function nav(){ $('#chapter-nav').innerHTML=topics.map((t,i)=>`<a href="#del-${i+1}" class="nav-item ${i===active?'active':''}" ${i===active?'aria-current="page"':''}><span class="nav-number">2.${i+1}</span><span>${t.short}</span>${progress[i]?'<b class="nav-done" aria-label="Träningsuppdrag klart">✓</b>':''}</a>`).join('');$('.home-link').classList.toggle('active',active<0);const n=Object.keys(progress).length;$('#progress-count').textContent=`${n} / 6`;$('#progress-bar').style.width=`${n/6*100}%`;}
function home(){
 active=-1;nav();const next=topics.findIndex((_,i)=>!progress[i]);const target=next<0?0:next;
 $('#main').innerHTML=`<div class="welcome"><div><p class="eyebrow">VÄLKOMMEN TILL DITT MATEMATIKLABB</p><h1>Här får algebra <em>liv.</em></h1></div><span class="chapter-chip"><span>◇</span> Matematik X · Kapitel 2</span></div>
 <section class="hero"><div class="hero-copy"><p class="eyebrow">BOKSTÄVER. MÖNSTER. MÖJLIGHETER.</p><h2>Små förändringar.<br><em>Stora upptäckter.</em></h2><p>Dra, bygg och testa dig fram. Upptäck varför matematiken fungerar — en idé i taget.</p><a class="primary" href="#del-${target+1}">${next===0?'Börja utforska':'Fortsätt utforska'} <span>↗</span></a></div><div class="hero-art" aria-label="Tre grupper med tre mintgröna prickar och två fasta gula prickar visar mönstret 3n plus 2"><span class="hero-index">FIGUR 03 / EN IDÉ SOM VÄXER</span><svg viewBox="0 0 420 320" aria-hidden="true"><defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#9fb9ad" opacity=".18"/></pattern></defs><rect width="420" height="320" fill="url(#grid)"/><g class="hero-floating">${[0,1,2].map(g=>`<g>${[0,1,2].map(j=>`<rect x="${78+g*78}" y="${136+j*32}" width="22" height="22" rx="6" fill="#57dbb7" opacity="${.7+g*.12}"/>`).join('')}<path d="M${73+g*78} 243h32" stroke="#57dbb7" stroke-opacity=".3"/><text x="${89+g*78}" y="263" fill="#83a99b" font-size="10" text-anchor="middle">${g+1}</text></g>`).join('')}<rect x="318" y="168" width="22" height="22" rx="6" fill="#e5b866"/><rect x="318" y="200" width="22" height="22" rx="6" fill="#e5b866"/><path d="M295 179h10m-5-5v10" stroke="#e5b866" opacity=".6"/></g></svg><div class="hero-formula">${math('3n+2')}</div><p class="hero-note">DET SOM VÄXER <span style="color:#57dbb7">●</span> &nbsp; + &nbsp; DET SOM STANNAR <span style="color:#e5b866">●</span></p></div></section>
 <div class="steps-strip"><div class="mini-step"><span>↔</span><div><strong>Utforska en idé</strong><p>Styr ditt eget experiment.</p></div></div><div class="mini-step"><span>▷</span><div><strong>Se sambanden</strong><p>Följ matematiken i rörelse.</p></div></div><div class="mini-step"><span>✧</span><div><strong>Utmana dig själv</strong><p>Pröva, tänk och försök igen.</p></div></div></div>
 <div class="section-heading"><div><p class="eyebrow">SEX VÄGAR TILL AHA</p><h2>Välj din nästa upptäckt.</h2></div><p>I din takt. Med plats att prova.</p></div>
 <section class="lab-grid" aria-label="Kapitlets sex delar">${topics.map((t,i)=>`<a class="lab-card" href="#del-${i+1}"><div class="card-top t${i}"><span class="card-number">2.${i+1}</span>${math(t.icon)}</div><div class="card-body"><h3>${t.title}</h3><p>${t.desc}</p><div class="card-meta"><span>${progress[i]?'✓ Träningsuppdrag klart':'◉ Labb &nbsp; · &nbsp; ▷ Film &nbsp; · &nbsp; ✧ Träna'}</span><b>↗</b></div></div></a>`).join('')}</section>
 <aside class="home-bottom"><div><strong>Det är tillåtet att inte veta. Än.</strong><p>Ledtrådar finns när du behöver dem. Välj utmaning när du vill gå vidare.</p></div><a href="#del-${target+1}" class="secondary">Till labbet →</a></aside>`;tex();}
function route(){cleanup();cleanup=()=>{};const m=location.hash.match(/^#del-([1-6])(?:\/(film|trana|forsta))?$/);if(!m){home();return}active=+m[1]-1;tab=m[2]==='film'?'film':m[2]==='trana'?'train':m[2]==='forsta'?'understand':'explore';lesson();}
function lesson(){nav();const t=topics[active];$('#main').innerHTML=`<div class="breadcrumbs"><a href="#hem">Överblick</a><span>/</span><span>2.${active+1} ${t.short}</span></div><div class="lesson-heading"><div><p class="eyebrow">KAPITEL 2.${active+1} · ${tab==='film'?'SE SAMBANDET':tab==='train'?'PRÖVA DIN FÖRSTÅELSE':tab==='understand'?'FÖRSTÅ SAMBANDET':'UTFORSKA EN IDÉ'}</p><h1>${tab==='explore'?t.lab:t.title}</h1><p>${tab==='explore'?t.intro:tab==='film'?'En visuell förklaring. Pausa, spola tillbaka och låt tankarna hinna med.':tab==='understand'?'Följ en idé genom bilder, symboler och tydliga mellanled. Prova sedan samma idé i labbet.':'Välj en nivå som passar dig idag. Ingen tidspress. Nya försök och ledtrådar hör till lärandet.'}</p></div><span class="lesson-step" aria-hidden="true">0${active+1}</span></div><div class="lesson-tabs" role="tablist" aria-label="Arbetssätt">${[['explore','↔','Utforska'],['understand','∑','Förstå'],['film','▷','Se filmen'],['train','✧','Träna']].map(([id,icon,name])=>`<button role="tab" id="tab-${id}" aria-controls="lesson-content" aria-selected="${tab===id}" data-tab="${id}"><span>${icon}</span>${name}</button>`).join('')}</div><div id="lesson-content" role="tabpanel" aria-labelledby="tab-${tab}"></div><div class="lab-actions"><button class="secondary" id="prev">${active===0?'← Överblick':'← Föregående del'}</button><button class="secondary" id="next">${active===5?'Till överblicken →':'Nästa upptäckt →'}</button></div>`;
 $$('[data-tab]').forEach(b=>b.onclick=()=>{location.hash=`del-${active+1}${b.dataset.tab==='film'?'/film':b.dataset.tab==='train'?'/trana':b.dataset.tab==='understand'?'/forsta':''}`});
 const tabs=$$('[role=tab]');tabs.forEach((b,i)=>b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length].focus()}});
 $('#prev').onclick=()=>location.hash=active===0?'hem':`del-${active}`;$('#next').onclick=()=>location.hash=active===5?'hem':`del-${active+2}`;
 if(tab==='explore')explore();else if(tab==='film')film();else if(tab==='understand')mountExplanation($('#lesson-content'),active);else train();tex();}
function explore(){
 const host=$('#lesson-content');host.innerHTML='<div id="studio-host"></div>';
 const mount=[mountExpressions,mountPatterns,mountTerms,h=>mountEquations(h,{bothSides:false}),mountStory,h=>mountEquations(h,{bothSides:true})][active];
 cleanup=mount($('#studio-host'))||(()=>{});
 host.insertAdjacentHTML('beforeend',`<aside class="studio-help-link"><div><h3>Se varför det fungerar</h3><p>${explanationPreview(active)}</p></div><a href="#del-${active+1}/forsta">Förklaring med LaTeX →</a></aside>`);
 tex(host);
}
function film(){const t=topics[active];$('#lesson-content').innerHTML=`<div class="film-layout"><section><div class="film-player"><video controls playsinline preload="metadata" poster="assets/posters/${t.film}.jpg" id="film"><source src="assets/films/${t.film}.mp4" type="video/mp4"><track kind="captions" srclang="sv" label="Svenska" src="assets/captions/${t.film}.vtt">Din webbläsare stöder inte video. <a href="assets/films/${t.film}.mp4">Hämta filmen.</a></video><div class="film-caption"><strong>${t.title}</strong><br>Följ en idé genom bilder, symboler och exempel. Ljudspåret innehåller musik; förklaringen finns i bild och text.</div></div><p class="film-note">Pausa när filmen ställer en fråga. Försök själv innan du spelar vidare. Slå på eller av undertexter med CC-knappen.</p></section><section class="control-panel"><h2>Titta aktivt</h2><p class="help">${t.question}</p><hr class="rule"><h2>Prova samma idé själv</h2><p class="help">Byt mellan filmen och labbet så många gånger du vill.</p><button class="primary" id="film-lab">Till det interaktiva labbet ↗</button><button class="secondary" id="film-train">Jag vill prova en uppgift →</button></section></div>`;$('#film-lab').onclick=()=>location.hash=`del-${active+1}`;$('#film-train').onclick=()=>location.hash=`del-${active+1}/trana`;const v=$('#film');cleanup=()=>v.pause();}
function renderExplanation(s){return esc(s).replace(/\\frac\{(-?\d+)\}\{(\d+)\}/g,(_,a,b)=>`(${a}/${b})`);}
function train(){task=generateTask(active,level,++seed);$('#lesson-content').innerHTML=`<div class="training"><section class="training-card"><div class="level-selector" role="group" aria-label="Välj svårighetsnivå">${[['start','Kom igång'],['explore','Utforska'],['challenge','Utmana']].map(([id,name])=>`<button data-level="${id}" class="${level===id?'active':''}" aria-pressed="${level===id}">${name}</button>`).join('')}</div><p class="task-label">ETT NYTT FÖRSÖK. EN NY UPPTÄCKT.</p><h2>${esc(task.prompt)}</h2><div class="task-tex">${math(task.tex)}</div><form id="answer-form"><div class="answer-row"><label for="answer">Ditt svar ${task.unit?`(${esc(task.unit)})`:''}<input autocomplete="off" inputmode="decimal" id="answer" class="answer-input" placeholder="Skriv ett tal" required aria-describedby="answer-tip"></label><button class="primary" type="submit">Kontrollera ↗</button></div><p class="help" id="answer-tip" style="font-size:10px;color:#5f735f">Decimaler kan skrivas med komma eller punkt.</p></form><div class="training-buttons"><button class="secondary" id="hint">Ge mig en ledtråd</button><button class="secondary" id="new-task">Ny uppgift ↻</button></div><div class="feedback" id="task-feedback" aria-live="polite"></div><div class="feedback" id="task-hint" hidden></div></section><aside class="control-panel"><h2>Din väg genom algebra</h2><div class="training-summary"><strong>${Object.keys(progress).length}<span style="font-size:17px;color:#7d9477"> / 6</span></strong>delar med ett löst träningsuppdrag.<p>En markering visar att du har löst en uppgift i delen. Fortsätt utforska för att befästa din förståelse.</p>${progress[active]?'<span class="completion-note">✓ Du har löst ett uppdrag här</span>':''}</div><hr class="rule"><h2>Fastnat?</h2><p class="help">Prova labbet, se filmen eller välj Kom igång. Du kan alltid göra ett nytt försök.</p><button class="secondary" id="train-lab">Öppna labbet →</button></aside></div>`;
 $$('[data-level]').forEach(b=>b.onclick=()=>{level=b.dataset.level;train();tex($('#lesson-content'));$(`[data-level="${level}"]`).focus()});$('#new-task').onclick=()=>{train();tex($('#lesson-content'));$('#answer').focus()};$('#hint').onclick=()=>{$('#task-hint').hidden=false;$('#task-hint').textContent=task.hint;$('#hint').disabled=true};$('#train-lab').onclick=()=>location.hash=`del-${active+1}`;
 $('#answer-form').onsubmit=e=>{e.preventDefault();const input=$('#answer').value.trim().replace(',','.').replace('−','-');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(input)){$('#task-feedback').className='feedback error';$('#task-feedback').textContent='Skriv ett tal, till exempel 4, −2 eller 1,5.';return}const answer=Number(input),ok=Number.isFinite(answer)&&Math.abs(answer-task.answer)<1e-7;$('#task-feedback').className='feedback '+(ok?'success':'error');if(ok){progress[active]=true;storage.set('algebra-progress-v1',progress);nav();$('#task-feedback').innerHTML=`<strong>Precis! Du har hittat sambandet.</strong><br>${renderExplanation(task.explanation)}<br><button class="secondary next-topic" id="correct-next">${active===5?'Till överblicken':'Vidare till nästa del'} →</button>`;$('#correct-next').onclick=()=>location.hash=active===5?'hem':`del-${active+2}`;$('.training-summary').innerHTML=`<strong>${Object.keys(progress).length}<span style="font-size:17px;color:#7d9477"> / 6</span></strong>delar med ett löst träningsuppdrag.<p>Fortsätt med nya uppgifter på samma eller en annan nivå.</p><span class="completion-note">✓ Du har löst ett uppdrag här</span>`;}else{$('#task-feedback').textContent='Inte riktigt än. Prova igen, eller använd ledtråden. Kontrollera tecken och räkneordning.';} };}
$('#teacher').onclick=()=>$('#about').showModal();$('.dialog-close').onclick=()=>$('#about').close();$('#about').onclick=e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#about').close()}};$('#reset-progress').onclick=()=>{progress={};storage.set('algebra-progress-v1',progress);nav();$('#about').close();route()};
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus({preventScroll:false})};
window.addEventListener('hashchange',()=>{route();window.scrollTo({top:0,behavior:'instant'});const selected=$(`[data-tab="${tab}"]`);if(/\/(film|trana|forsta)$/.test(location.hash)&&selected)selected.focus({preventScroll:true});else $('#main').focus({preventScroll:true});});window.addEventListener('DOMContentLoaded',()=>tex());route();
